function assertFiniteNumber(path, value) {
  if (value == null) return;
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(`${path} must be a finite number`);
}

async function main(ctx) {
  const input = ctx.input || {};

  const starshipId = String(input.starshipId ?? ctx.env('STARSHIP_ID') ?? '');
  if (!starshipId) throw new Error('starshipId is required (or STARSHIP_ID must be available in env)');

  const accountId = input.account_id;
  if (accountId == null) throw new Error('account_id is required');
  assertFiniteNumber('account_id', accountId);

  const accountName = (typeof input.account_name === 'string') ? input.account_name.trim() : '';
  if (!accountName) throw new Error('account_name is required (dataset constraint)');

  const row = {
    account_id: accountId,
    account_name: accountName,
    status: 'disqualified'
  };

  if (typeof input.disqualify_reason === 'string' && input.disqualify_reason.trim()) {
    row.disqualify_reason = input.disqualify_reason.trim();
  }
  if (typeof input.notes === 'string' && input.notes.trim()) {
    row.notes = input.notes.trim();
  }

  return {
    starshipId,
    datasetSlug: 'accounts',
    mode: 'upsert',
    rows: [row]
  };
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp.body;
  if (body && typeof body === 'object' && body.success === true && 'data' in body) return body.data;
  return body ?? resp;
}
